window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e6f4e826b98ae53d"]={"versions": [{"id": "FIG-e6f4e826b98ae53d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherbelegungsdiagramm (Data Structure Layout) im Kontext des AUTOSAR Function Inhibition Managers (FiM), Bestandteil der System Services des AUTOSAR Basic Software (BSW) Stacks. Das Diagramm visualisiert die interne organisationale Verknüpfung zwischen Function Identifiers (FIDs), den ihnen zugeordneten Diagnose-Events (<code>EventId</code>) und den korrespondierenden Inhibit-Masken zur Laufzeitberechnung des Freigabestatus von Funktionalitäten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei funktionale Entitätstypen in tabellarischen Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>FID-Array (FID Status Table)</strong>: Fortlaufend indexierte Tabelle (Index 1 bis 7) mit Einträgen für aktive Funktionskennungen (<code>FID_m</code>, <code>FID_r</code>, <code>FID_c</code>, <code>FID_f</code>, <code>FID_t</code>) sowie nicht belegten Slots (<code>FID_unused</code>).</li>\n<li><strong>Assigned Events Tables</strong>: Listen zugeordneter Diagnoseereignisse je FID, dargestellt für <code>FID_m</code> mit vier Ereignissen (<code>FID_m_event_1</code> bis <code>FID_m_event_4</code>) und für <code>FID_t</code> mit drei Ereignissen (<code>FID_t_event_1</code> bis <code>FID_t_event_3</code>).</li>\n<li><strong>Inhibit Masks Tables</strong>: Zu den Ereignislisten parallel geführte Maskenarrays mit identischer Mächtigkeit (<code>FID_m_mask_1</code> bis <code>FID_m_mask_4</code> für <code>FID_m</code> bzw. <code>FID_t_mask_1</code> bis <code>FID_t_mask_3</code> für <code>FID_t</code>).</li>\n<li><strong>Beziehungen</strong>: Gerichtete <code>uses</code>-Referenzen verknüpfen den jeweiligen FID-Eintrag mit der zugehörigen Event- und Maskenkonfiguration. Farblich korrespondieren grün (<code>FID_m</code>) und orange (<code>FID_t</code>) zwischen FID und den zugehörigen Tabellenblöcken.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturmodell ohne dynamischen Zeitablauf. Das funktionale Schema beschreibt die Auswertung zur Ermittlung der Funktionsfreigabe:</p>\n<ol class=\"fig-list\">\n<li>Adressierung eines FIDs über dessen numerischen Index im FID-Array.</li>\n<li>Auflösung der referenzierten Ereignisliste (<code>Assigned events for FID_x</code>).</li>\n<li>Positionsbezogene Verknüpfung jedes Ereignisses mit der korrespondierenden Maske (<code>Inhibit masks for FID_x</code>).</li>\n<li>Ermittlung des Gesamthemmstatus der FID über die bitweise Prüfung des aktuellen Event-Status gegen die Inhibit-Maske für alle zugewiesenen Ereignisse.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Implementierungsbeispiel für BSW-Entwickler des FiM zur speicher- und laufzeiteffizienten Abbildung von n:m-Beziehungen zwischen Funktionskennungen und Diagnose-Events. Nicht belegte Einträge (<code>FID_unused</code>) verdeutlichen ein fixes Array-Layout, das Lücken im ID-Raum zulässt. Die 1:1-Zuordnung zwischen Elementen der Event-Liste und Elementen der Masken-Liste erfordert konsistente Dimensionierung der konfigurierten Tabellen je Funktion.</p>"}, {"id": "FIG-1c754955938f5b6d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherbelegungsdiagramm (Data Structure Layout) im Kontext des AUTOSAR Function Inhibition Managers (FiM), Bestandteil der System Services des AUTOSAR Basic Software (BSW) Stacks. Das Diagramm visualisiert die interne organisationale Verknüpfung zwischen Function Identifiers (FIDs), den ihnen zugeordneten Diagnose-Events (<code>EventId</code>) und den korrespondierenden Inhibit-Masken zur Laufzeitberechnung des Freigabestatus von Funktionalitäten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei funktionale Entitätstypen in tabellarischen Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>FID-Array (FID Status Table)</strong>: Fortlaufend indexierte Tabelle (Index 1 bis 7) mit Einträgen für aktive Funktionskennungen (<code>FID_m</code>, <code>FID_r</code>, <code>FID_c</code>, <code>FID_f</code>, <code>FID_t</code>) sowie nicht belegten Slots (<code>FID_unused</code>).</li>\n<li><strong>Assigned Events Tables</strong>: Listen zugeordneter Diagnoseereignisse je FID, dargestellt für <code>FID_m</code> mit vier Ereignissen (<code>FID_m_event_1</code> bis <code>FID_m_event_4</code>) und für <code>FID_t</code> mit drei Ereignissen (<code>FID_t_event_1</code> bis <code>FID_t_event_3</code>).</li>\n<li><strong>Inhibit Masks Tables</strong>: Zu den Ereignislisten parallel geführte Maskenarrays mit identischer Mächtigkeit (<code>FID_m_mask_1</code> bis <code>FID_m_mask_4</code> für <code>FID_m</code> bzw. <code>FID_t_mask_1</code> bis <code>FID_t_mask_3</code> für <code>FID_t</code>).</li>\n<li><strong>Beziehungen</strong>: Gerichtete <code>uses</code>-Referenzen verknüpfen den jeweiligen FID-Eintrag mit der zugehörigen Event- und Maskenkonfiguration. Farblich korrespondieren grün (<code>FID_m</code>) und orange (<code>FID_t</code>) zwischen FID und den zugehörigen Tabellenblöcken.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturmodell ohne dynamischen Zeitablauf. Das funktionale Schema beschreibt die Auswertung zur Ermittlung der Funktionsfreigabe:</p>\n<ol class=\"fig-list\">\n<li>Adressierung eines FIDs über dessen numerischen Index im FID-Array.</li>\n<li>Auflösung der referenzierten Ereignisliste (<code>Assigned events for FID_x</code>).</li>\n<li>Positionsbezogene Verknüpfung jedes Ereignisses mit der korrespondierenden Maske (<code>Inhibit masks for FID_x</code>).</li>\n<li>Ermittlung des Gesamthemmstatus der FID über die bitweise Prüfung des aktuellen Event-Status gegen die Inhibit-Maske für alle zugewiesenen Ereignisse.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Implementierungsbeispiel für BSW-Entwickler des FiM zur speicher- und laufzeiteffizienten Abbildung von n:m-Beziehungen zwischen Funktionskennungen und Diagnose-Events. Nicht belegte Einträge (<code>FID_unused</code>) verdeutlichen ein fixes Array-Layout, das Lücken im ID-Raum zulässt. Die 1:1-Zuordnung zwischen Elementen der Event-Liste und Elementen der Masken-Liste erfordert konsistente Dimensionierung der konfigurierten Tabellen je Funktion.</p>"}], "trans": [{"from": "FIG-e6f4e826b98ae53d", "to": "FIG-1c754955938f5b6d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
